// Hand-written Verilog testbench for AC-MVP-005, AC-MVP-006, AC-MVP-007 and
// AC-MVP-008. It is deliberately not generated by ShyHDL: a failure here must be
// a DUT failure, never a testbench-generation failure.
//
// The testbench owns the clock, so the edge counters below are independent
// evidence that no clock edge happened when the test claims none did.
//
// Protocol: exactly one `SHYHDL-AC-PASS sequential ...` line on success,
// otherwise `SHYHDL-AC-FAIL sequential ...` lines. A run that prints no verdict
// is a failure, never a pass.
//
// Expects the frontend-generated modules: Register_W8, Pipe8, SeqTop.

`timescale 1ns/1ps

module tb_sequential;
    localparam integer EXPECTED_CHECKS = 48;

    reg       clk, rst_n, enable;
    reg [7:0] d;

    wire [7:0] q_reg;
    wire [7:0] q_pipe, stage_pipe;
    wire [7:0] q_top, pq_top, pstage_top;

    integer failures, checks, clocks, resets;

    Register_W8 dut_reg  (.d(d), .enable(enable), .rst_n(rst_n), .clk(clk), .q(q_reg));
    Pipe8       dut_pipe (.d(d), .enable(enable), .rst_n(rst_n), .clk(clk),
                          .q(q_pipe), .stage1_out(stage_pipe));
    SeqTop      dut_top  (.d(d), .enable(enable), .rst_n(rst_n), .clk(clk),
                          .q(q_top), .pq(pq_top), .pstage(pstage_top));

    always @(posedge clk) clocks = clocks + 1;
    always @(negedge rst_n) resets = resets + 1;

    // Half period 5 ns: posedges at 5, 15, 25, ...; negedges at 10, 20, 30, ...
    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    task expect_q;
        input [255:0] what;
        input [7:0]   got;
        input [7:0]   want;
        begin
            checks = checks + 1;
            if (got !== want) begin
                failures = failures + 1;
                if (failures <= 12)
                    $display("SHYHDL-AC-FAIL sequential %0s got=%b want=%b (t=%0t rst_n=%b enable=%b d=%b)",
                             what, got, want, $time, rst_n, enable, d);
            end
        end
    endtask

    // AC-MVP-006: an unknown value must never be accepted as the expected zero.
    // A reduction XOR is `x` as soon as one bit is `x`, in plain Verilog-2005.
    task expect_known;
        input [255:0] what;
        input [7:0]   got;
        begin
            checks = checks + 1;
            if ((^got) === 1'bx) begin
                failures = failures + 1;
                if (failures <= 12)
                    $display("SHYHDL-AC-FAIL sequential %0s is unknown (t=%0t)", what, $time);
            end
        end
    endtask

    task expect_int;
        input [255:0] what;
        input integer got;
        input integer want;
        begin
            checks = checks + 1;
            if (got !== want) begin
                failures = failures + 1;
                if (failures <= 12)
                    $display("SHYHDL-AC-FAIL sequential %0s got=%0d want=%0d (t=%0t)",
                             what, got, want, $time);
            end
        end
    endtask

    initial begin
        failures = 0;
        checks = 0;
        clocks = 0;
        resets = 0;
        rst_n = 1'b1;
        enable = 1'b0;
        d = 8'h00;

        // ---- AC-MVP-006: the reset must be produced by a real 1 -> 0 fall ----
        #2;                              // t = 2, the first posedge is at t = 5
        rst_n = 1'b0;
        #1;                              // t = 3

        // ---- AC-MVP-005: asynchronous reset acts between clock edges ----
        expect_int("ac005.no_clock_edge_before_reset_effect", clocks, 0);
        expect_int("ac006.reset_is_a_real_fall", resets, 1);
        expect_q("ac005.reset_between_edges.reg", q_reg, 8'h00);
        expect_q("ac005.reset_between_edges.pipe_q", q_pipe, 8'h00);
        expect_q("ac005.reset_between_edges.pipe_stage", stage_pipe, 8'h00);
        expect_q("ac005.reset_between_edges.top", q_top, 8'h00);
        expect_q("ac005.reset_between_edges.top_pipe", pq_top, 8'h00);
        expect_q("ac005.reset_between_edges.top_stage", pstage_top, 8'h00);
        expect_known("ac006.reset_not_inferred_from_x.reg", q_reg);
        expect_known("ac006.reset_not_inferred_from_x.pipe", q_pipe);

        // ---- AC-MVP-006: reset held low across clock edges and data changes ----
        d = 8'hFF;
        enable = 1'b1;
        #4;                              // t = 7, posedge at t = 5 has happened
        expect_int("ac006.clock_edges_while_held_1", clocks, 1);
        expect_q("ac006.held_low.reg", q_reg, 8'h00);
        expect_q("ac006.held_low.pipe", q_pipe, 8'h00);
        expect_q("ac006.held_low.top", q_top, 8'h00);

        #5;                              // t = 12
        d = 8'hA5;
        #5;                              // t = 17, posedge at t = 15 has happened
        expect_int("ac006.clock_edges_while_held_2", clocks, 2);
        expect_q("ac006.held_low_after_data_change.reg", q_reg, 8'h00);
        expect_q("ac006.held_low_after_data_change.pipe", q_pipe, 8'h00);
        expect_q("ac006.held_low_after_data_change.top", q_top, 8'h00);

        // ---- release the reset and capture ----
        rst_n = 1'b1;                    // t = 17, a real 0 -> 1
        d = 8'h5A;
        enable = 1'b1;
        @(posedge clk);                  // t = 25
        #1;                              // t = 26
        expect_int("ac006.clock_edges_before_release", clocks, 3);
        expect_q("ac006.capture_after_release.reg", q_reg, 8'h5A);
        expect_q("ac006.capture_after_release.top", q_top, 8'h5A);
        expect_q("ac008.pipeline_loads_stage1", stage_pipe, 8'h5A);
        expect_q("ac008.pipeline_keeps_old_value", q_pipe, 8'h00);
        expect_q("ac008.top_loads_stage1", pstage_top, 8'h5A);
        expect_q("ac008.top_keeps_old_value", pq_top, 8'h00);

        // ---- AC-MVP-007: enable low holds the output while the input moves ----
        enable = 1'b0;
        d = 8'h3C;
        @(posedge clk);                  // t = 35
        @(posedge clk);                  // t = 45
        @(posedge clk);                  // t = 55
        #1;                              // t = 56
        expect_int("ac007.clock_edges_while_disabled", clocks, 6);
        expect_q("ac007.enable_low_holds.reg", q_reg, 8'h5A);
        expect_q("ac007.enable_low_holds.top", q_top, 8'h5A);
        expect_q("ac007.enable_low_holds.pipe", q_pipe, 8'h00);
        expect_q("ac007.enable_low_holds.pipe_stage", stage_pipe, 8'h5A);

        // ---- AC-MVP-005 again: a second asynchronous clear ----
        rst_n = 1'b0;                    // t = 56
        #1;                              // t = 57
        expect_q("ac005.second_async_reset.reg", q_reg, 8'h00);
        expect_q("ac005.second_async_reset.pipe_q", q_pipe, 8'h00);
        expect_q("ac005.second_async_reset.pipe_stage", stage_pipe, 8'h00);
        expect_q("ac005.second_async_reset.top", q_top, 8'h00);
        expect_q("ac005.second_async_reset.top_pipe", pq_top, 8'h00);
        expect_q("ac005.second_async_reset.top_stage", pstage_top, 8'h00);

        // ---- AC-MVP-008: the second stage reads the previous first stage ----
        rst_n = 1'b1;                    // t = 57
        enable = 1'b1;
        d = 8'h11;
        @(posedge clk);                  // t = 65
        #1;                              // t = 66
        expect_q("ac008.first_edge.stage1", stage_pipe, 8'h11);
        expect_q("ac008.first_edge.q", q_pipe, 8'h00);
        expect_q("ac008.first_edge.top_stage1", pstage_top, 8'h11);
        expect_q("ac008.first_edge.top_q", pq_top, 8'h00);

        d = 8'h22;
        @(posedge clk);                  // t = 75
        #1;                              // t = 76
        expect_q("ac008.second_edge.stage1", stage_pipe, 8'h22);
        expect_q("ac008.second_edge.q", q_pipe, 8'h11);
        expect_q("ac008.second_edge.top_stage1", pstage_top, 8'h22);
        expect_q("ac008.second_edge.top_q", pq_top, 8'h11);

        d = 8'h33;
        @(posedge clk);                  // t = 85
        #1;                              // t = 86
        expect_q("ac008.third_edge.stage1", stage_pipe, 8'h33);
        expect_q("ac008.third_edge.q", q_pipe, 8'h22);
        expect_q("ac008.third_edge.top_stage1", pstage_top, 8'h33);
        expect_q("ac008.third_edge.top_q", pq_top, 8'h22);

        if (failures == 0 && checks == EXPECTED_CHECKS)
            $display("SHYHDL-AC-PASS sequential checks=%0d clocks=%0d", checks, clocks);
        else
            $display("SHYHDL-AC-FAIL sequential failures=%0d checks=%0d expected_checks=%0d",
                     failures, checks, EXPECTED_CHECKS);
        $finish;
    end

    initial begin
        #100000;
        $display("SHYHDL-AC-FAIL sequential timeout at %0t: no verdict was printed", $time);
        $finish;
    end
endmodule
